/* Rebuilt, source-checked working tables. Original sheets stay available as evidence. */
(() => {
  'use strict';
  const registry = window.DECK_ENHANCEMENTS ||= {};
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({source:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 8h8M8 12h8M8 16h5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',minus:'<path d="M5 12h14"/>',plus:'<path d="M5 12h14M12 5v14"/>',play:'<path d="m9 5 10 7-10 7z"/>',pause:'<path d="M9 5v14M15 5v14"/>',replay:'<path d="M4 10a8 8 0 1 1 .9 7M4 4v6h6"/>'})[name]}</svg>`;
  const stations = [
    {short:'桃源大道',name:'重庆琥珀传能桃源大道超充站',guns:18,electric:.32,old:[.11,.09,.09],fee:[.20,.15,.15]},
    {short:'双碑嘉陵',name:'琥珀双碑天阅嘉陵充电站',guns:18,electric:.37,old:[.11,.09,.09],fee:[.17,.14,.14]},
    {short:'界石超充',name:'重庆琥珀传能界石超充站（重庆捷充）',guns:26,electric:.38,old:[.11,.09,.09],fee:[.15,.10,.11]}
  ];
  const users=['私家车','非会员营运车','会员'];
  const periods=['00:00 – 08:00','08:00 – 11:00','11:00 – 17:00','17:00 – 20:00','20:00 – 22:00','22:00 – 23:59'];
  const f = v => v.toFixed(2);
  const note = text => `<p class="pc-note"><span>注</span>${text}</p>`;
  const sourceAssets = {pricing:'assets/pricing.jpg',configuration:'assets/configuration.jpg'};
  const sourceDialog = (key,title) => `<dialog class="pc-source-dialog" data-pc-dialog aria-label="${title}原表对照" data-deck-no-swipe><div class="pc-source-shell"><header><div><span>ORIGINAL / 原始材料</span><h2>${title}</h2></div><div class="pc-source-tools"><button type="button" data-pc-zoom="-1" aria-label="缩小原表">${icon('minus')}</button><output data-pc-zoom-label>适应窗口</output><button type="button" data-pc-zoom="1" aria-label="放大原表">${icon('plus')}</button><button type="button" data-pc-zoom="0">重置</button><button type="button" data-pc-close aria-label="关闭原表对照">${icon('close')}</button></div></header><div class="pc-source-scroll" tabindex="0" aria-label="原表，可滚动查看"><img src="${sourceAssets[key]}" alt="${title}完整原始表格" data-pc-source-img></div><footer><b>原表保留原貌</b><span>主页面按白 / 橙 / 黑重绘关键字段；可对照原始价格与配置口径。</span></footer></div></dialog>`;
  const controls = `<div class="pc-motion"><button type="button" data-pc-play aria-label="播放逐项讲解">${icon('play')}</button><button type="button" data-pc-replay aria-label="重播逐项讲解">${icon('replay')}</button></div>`;
  const tablePricing = s => `<table class="pc-table pc-price-table"><thead><tr><th>用户人群</th><th data-pc-col="0">当前服务费</th><th data-pc-col="0">建议服务费</th><th data-pc-col="1">当前总价</th><th data-pc-col="1">建议总价</th><th data-pc-col="2">调整幅度</th></tr></thead><tbody>${users.map((u,i)=>`<tr data-pc-row="${i}" class="${i===0?'is-selected':''}"><th scope="row"><button type="button" data-pc-user="${i}"><span>0${i+1}</span>${u}</button></th><td data-pc-col="0">${f(s.old[i])}</td><td data-pc-col="0" class="pc-table-proposed">${f(s.fee[i])}</td><td data-pc-col="1">${f(s.electric+s.old[i])}</td><td data-pc-col="1" class="pc-table-proposed">${f(s.electric+s.fee[i])}</td><td data-pc-col="2">+${f(s.fee[i]-s.old[i])}</td></tr>`).join('')}</tbody></table>`;
  const tableConfig = s => `<table class="pc-table pc-config-table"><thead><tr><th>生效时段</th><th data-pc-col="0">电费</th><th data-pc-col="0">私家车服务费</th><th data-pc-col="1">私家车总价</th><th data-pc-col="2">会员 / 营运服务费</th><th data-pc-col="2">会员 / 营运总价</th></tr></thead><tbody>${periods.map((t,i)=>{const e=i===0?s.electric:[0,.72,1.10,.72,1.10,.72][i];return `<tr data-pc-row="${i}" class="${i===0?'is-selected':''}"><th scope="row"><button type="button" data-pc-period="${i}"><span>0${i+1}</span>${t}</button></th><td data-pc-col="0">${f(e)}</td><td data-pc-col="0">${f(s.fee[0])}</td><td data-pc-col="1" class="pc-table-proposed">${f(e+s.fee[0])}</td><td data-pc-col="2">${f(s.fee[1])}</td><td data-pc-col="2" class="pc-table-proposed">${f(e+s.fee[1])}</td></tr>`}).join('')}</tbody></table>`;
  const steps = kind => kind==='pricing' ? [
    ['01','拆开价格','电费不变，调整服务费','先拆电费与服务费，明确可调空间；每一项价格都要能核对来源。'],
    ['02','比较人群','核对最终到手价','同站、同时段比较人群价格梯度；会员与营运车是否同价，由具体方案决定。'],
    ['03','验证效果','调价只是验证的起点','落地后观察订单、电量和用户结构，同时核算补贴与度均收益。']
  ] : [
    ['01','价格组成','电费 + 服务费 = 总价','按时段记录电费与服务费，检查前后相加是否一致。'],
    ['02','人群权益','明确身份与适用优先级','本摘录中会员与非会员营运车价格相同；不同站点的减价幅度不同。'],
    ['03','活动叠加','核对用户最终支付价','核对会员价、优惠券与促销组合，避免多重优惠产生意外价差。'],
    ['04','生效核验','展示、时间与结算一致','保留生效版本、调价原因和观察窗口，便于执行核验与复盘。']
  ];
  function stepNav(kind){return `<nav class="pc-step-nav" aria-label="讲解步骤">${steps(kind).map((s,i)=>`<button type="button" data-pc-step="${i}" aria-pressed="${i===0}" class="${i===0?'is-active':''}"><span>${s[0]}</span>${s[1]}<i></i></button>`).join('')}</nav>`}
  function header(kicker,title,desc){return `<div class="report-head pc-head"><span class="report-kicker">${kicker}</span><h1>${title}</h1><p class="report-deck">${desc}</p></div>`}
  function body(kind){const config=kind==='config',s=stations[0];return `<div class="report-body pc-root pc-${kind}" data-pc-kind="${kind}" data-pc-focus="0">
    <div class="pc-topline"><div class="pc-station-tabs" role="group" aria-label="选择案例场站">${stations.slice(0,config?2:3).map((x,i)=>`<button type="button" data-pc-station="${i}" aria-pressed="${i===0}" class="${i===0?'is-active':''}"><span>0${i+1}</span>${x.short}</button>`).join('')}</div><button type="button" class="pc-source-open" data-pc-source>${icon('source')}原表对照</button></div>
    <div class="pc-workspace"><section class="pc-ledger" aria-label="${config?'分时分人群配置摘录':'谷时定价建议摘录'}"><header class="pc-ledger-header"><div><span>${config?'CONFIGURATION / 配置摘录':'PRICING PROPOSAL / 谷时摘录'}</span><h2 data-pc-station-name>${s.name}</h2></div><div class="pc-ledger-meta" data-pc-meta>${config?'直连 · 已上线':s.guns+' 把枪 · 谷时'}<small>单位：元 / 度</small></div></header><div class="pc-table-scroll" data-deck-no-swipe data-pc-table>${config?tableConfig(s):tablePricing(s)}</div><div class="pc-ledger-footer"><span>${config?'配置颗粒度':'比较条件'}</span><b>${config?'场站 × 时段 × 人群 × 价格 / 优惠':'同一场站 · 同一时段 · 同一价格口径'}</b><span class="pc-rebuilt">重绘摘录</span></div>${config?'':'<div class="pc-price-annotation"><span>人群价差</span><strong data-pc-gap>2 <small>分</small><i>→</i>5 <small>分</small></strong><p data-pc-gap-copy>私家车与会员的价差扩大；本方案营运车与会员同价。</p></div>'}</section>
    <aside class="pc-narrative"><div class="pc-narrative-top"><span>READ THE DECISION</span>${controls}</div>${stepNav(kind)}<div class="pc-live-explanation" aria-live="polite"><span class="pc-step-counter" data-pc-counter>01 / ${config?'04':'03'}</span><h2 data-pc-heading>${steps(kind)[0][2]}</h2><p data-pc-copy>${steps(kind)[0][3]}</p></div><div class="pc-equation-panel"><div><span data-pc-selection>${config?'00:00 – 08:00 · 私家车':'私家车 · 建议总价'}</span><small data-pc-equation-context>${config?'选中行核验':'选中人群核验'}</small></div><div class="pc-arithmetic"><span><b data-pc-electric>0.32</b><small>电费</small></span><i>+</i><span><b data-pc-fee>0.20</b><small>服务费</small></span><i>=</i><span class="pc-result"><b data-pc-total>0.52</b><small>总价</small></span></div></div></aside></div>
    <div class="pc-takeaway"><b>${config?'让变更可追溯':'把方案与结果分开看'}</b><p>${config?'记录调价原因、目标人群、生效时间与观察窗口，让价格动作对应到经营变化。':'分层调价可以采用不同幅度；是否改善经营，仍需用订单、电量、补贴和度均收益验证。'}</p></div>
    ${note(config?'摘录原表的两站六时段配置；会员 / 营运列合并展示同价结果。实际执行以核对后的生效版本为准。':'原表价格建议的谷时摘录，非调价后经营结果。未重绘竞争站与区块均价字段；样本范围需另行核对。')}
    ${sourceDialog(config?'configuration':'pricing',config?'分时段与分人群配置':'场站分层定价建议')}
  </div>`}
  function mount(root){
    const panel=root.querySelector('.pc-root'),kind=panel.dataset.pcKind,config=kind==='config',reduced=matchMedia('(prefers-reduced-motion: reduce)'),dialog=panel.querySelector('[data-pc-dialog]');
    let station=0,selected=0,step=0,timer=0,playing=false,disposed=false,zoom=1,closeTimer=0,returnFocus=null;
    const $=s=>panel.querySelector(s),$$=s=>[...panel.querySelectorAll(s)];
    const clear=()=>{clearTimeout(timer);timer=0};
    function animate(el){if(reduced.matches)return;el.animate([{opacity:.18,transform:'translateY(7px)',filter:'blur(3px)'},{opacity:1,transform:'translateY(0)',filter:'blur(0)'}],{duration:460,easing:'cubic-bezier(.16,1,.3,1)'})}
    function syncPlay(){const b=$('[data-pc-play]');b.innerHTML=icon(playing?'pause':'play');b.setAttribute('aria-label',playing?'暂停逐项讲解':'播放逐项讲解');panel.classList.toggle('is-playing',playing&&!document.hidden&&!reduced.matches);clear();if(playing&&!disposed&&!document.hidden&&!dialog.open&&!reduced.matches)timer=setTimeout(()=>{setStep((step+1)%steps(kind).length);syncPlay()},4200)}
    function setStep(n){step=n;panel.dataset.pcFocus=String(n);$$('[data-pc-step]').forEach((b,i)=>{b.classList.toggle('is-active',i===n);b.setAttribute('aria-pressed',String(i===n))});$('[data-pc-counter]').textContent=`0${n+1} / 0${steps(kind).length}`;$('[data-pc-heading]').textContent=steps(kind)[n][2];$('[data-pc-copy]').textContent=steps(kind)[n][3];animate($('.pc-live-explanation'));if(config)sum()}
    function sum(){const s=stations[station],member=config&&(step===1||step===2),e=config?(selected===0?s.electric:[0,.72,1.10,.72,1.10,.72][selected]):s.electric,fee=s.fee[config?(member?1:0):selected];$('[data-pc-selection]').textContent=config?periods[selected]+(member?' · 会员 / 营运':' · 私家车'):users[selected]+' · 建议总价';$('[data-pc-equation-context]').textContent=config?(step===2?'活动叠加前':step===3?'生效版本核验':'选中行核验'):'选中人群核验';$('[data-pc-electric]').textContent=f(e);$('[data-pc-fee]').textContent=f(fee);$('[data-pc-total]').textContent=f(e+fee);$$('[data-pc-row]').forEach((row,i)=>row.classList.toggle('is-selected',i===selected));animate($('.pc-arithmetic'))}
    function selectStation(n){station=n;selected=0;const s=stations[n];$$('[data-pc-station]').forEach((b,i)=>{b.classList.toggle('is-active',i===n);b.setAttribute('aria-pressed',String(i===n))});$('[data-pc-station-name]').textContent=s.name;$('[data-pc-meta]').innerHTML=(config?'直连 · 已上线':s.guns+' 把枪 · 谷时')+'<small>单位：元 / 度</small>';$('[data-pc-table]').innerHTML=config?tableConfig(s):tablePricing(s);if(!config){$('[data-pc-gap]').innerHTML=`${Math.round((s.old[0]-s.old[2])*100)} <small>分</small><i>→</i>${Math.round((s.fee[0]-s.fee[2])*100)} <small>分</small>`;$('[data-pc-gap-copy]').textContent=n===2?'私家车与会员价差由 2 分扩大到 4 分；本方案会员比营运车高 1 分。':'私家车与会员价差扩大；本方案营运车与会员同价。'}sum();animate($('[data-pc-table]'))}
    function setZoom(n){zoom=n===0?1:Math.min(3,Math.max(1,zoom+n*.5));$('[data-pc-source-img]').style.width=zoom*100+'%';$('[data-pc-zoom-label]').textContent=zoom===1?'适应窗口':Math.round(zoom*100)+'%'}
    function openSource(button){returnFocus=button;clearTimeout(closeTimer);dialog.classList.remove('is-closing');dialog.showModal();setZoom(0);syncPlay();dialog.querySelector('[data-pc-close]').focus()}
    function closeSource(){if(!dialog.open)return;dialog.classList.add('is-closing');clearTimeout(closeTimer);closeTimer=setTimeout(()=>{dialog.close();dialog.classList.remove('is-closing');returnFocus?.focus();syncPlay()},reduced.matches?0:240)}
    const click=e=>{let el=e.target.closest('[data-pc-station],[data-pc-step],[data-pc-user],[data-pc-period],[data-pc-play],[data-pc-replay],[data-pc-source],[data-pc-close],[data-pc-zoom]');if(!el)return;if(el.hasAttribute('data-pc-station')){selectStation(+el.dataset.pcStation)}else if(el.hasAttribute('data-pc-step')){playing=false;setStep(+el.dataset.pcStep);syncPlay()}else if(el.hasAttribute('data-pc-user')||el.hasAttribute('data-pc-period')){selected=+(el.dataset.pcUser??el.dataset.pcPeriod);sum()}else if(el.hasAttribute('data-pc-play')){playing=!playing;syncPlay()}else if(el.hasAttribute('data-pc-replay')){setStep(0);selectStation(station);playing=!reduced.matches;syncPlay()}else if(el.hasAttribute('data-pc-source'))openSource(el);else if(el.hasAttribute('data-pc-close'))closeSource();else if(el.hasAttribute('data-pc-zoom'))setZoom(+el.dataset.pcZoom)};
    const dialogKey=e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();closeSource()}if(['ArrowLeft','ArrowRight','PageUp','PageDown','Home','End'].includes(e.key))e.stopPropagation()};
    const cancel=e=>{e.preventDefault();closeSource()};
    const backdrop=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSource()}};
    const motionChange=()=>{if(reduced.matches)playing=false;syncPlay()};
    panel.addEventListener('click',click);dialog.addEventListener('keydown',dialogKey);dialog.addEventListener('cancel',cancel);dialog.addEventListener('click',backdrop);document.addEventListener('visibilitychange',syncPlay);reduced.addEventListener('change',motionChange);panel.classList.add('pc-ready');
    return()=>{disposed=true;clear();clearTimeout(closeTimer);if(dialog.open)dialog.close();panel.removeEventListener('click',click);dialog.removeEventListener('keydown',dialogKey);dialog.removeEventListener('cancel',cancel);dialog.removeEventListener('click',backdrop);document.removeEventListener('visibilitychange',syncPlay);reduced.removeEventListener('change',motionChange)};
  }
  registry[7]={title:'把定价判断，写成一份可核对的方案',html:header('07 / PRICING IN PRACTICE','把定价判断，写成可核对的<em>方案。</em>','从同一场站的谷时价格出发，拆解费用、比较人群，再验证经营结果。')+body('pricing'),mount};
  registry[8]={title:'让每一项价格，都落到执行单元',html:header('08 / FROM STRATEGY TO EXECUTION','让每一项价格，落到<em>执行单元。</em>','场站、时段、人群与权益对应到同一版本，策略才能准确执行。')+body('config'),mount};
})();
